using App.Repositories;

namespace App;

/// <summary>The in-memory repositories, for tests and for trying the services without a database.</summary>
public class MemoryUnitOfWork : IUnitOfWork
{
    public ICustomerRepository Customers { get; } = new MemoryCustomerRepository();
    public ICategoryRepository Categories { get; } = new MemoryCategoryRepository();
    public IProductRepository Products { get; } = new MemoryProductRepository();
    public IOrderRepository Orders { get; } = new MemoryOrderRepository();
    public IOrderLineRepository OrderLines { get; } = new MemoryOrderLineRepository();
    public ITagRepository Tags { get; } = new MemoryTagRepository();
    public IProductTagRepository ProductTags { get; } = new MemoryProductTagRepository();
    public IAuditLogRepository AuditLogRows { get; } = new MemoryAuditLogRepository();

    /// <summary>Memory has no transactions: changes are kept as they are made.</summary>
    public Task<T> TransactionAsync<T>(Func<IUnitOfWork, Task<T>> work) => work(this);

    public Task TransactionAsync(Func<IUnitOfWork, Task> work) =>
        TransactionAsync<bool>(async uow =>
        {
            await work(uow);
            return true;
        });
}

